Guid yachtId = Get<Guid>("YachtId");
var yachtEsq = new EntitySchemaQuery(UserConnection.EntitySchemaManager, "UsrYacht");
var driveTypeColumn = yachtEsq.AddColumn("UsrDriveType");
var yachtEntity = yachtEsq.GetEntity(UserConnection, yachtId);
Guid driveTypeId = yachtEntity != null ? yachtEntity.GetTypedColumnValue<Guid>(driveTypeColumn.Name) : Guid.Empty;
Set("DriveTypeIdParameter", driveTypeId);
var esq = new EntitySchemaQuery(UserConnection.EntitySchemaManager, "UsrYacht");
var passengerCountColumn = esq.AddColumn("UsrPassengerCount");
var priceColumn = esq.AddColumn("UsrPricePerDay");
var typeFilter = esq.CreateFilterWithParameters(FilterComparisonType.Equal, "UsrDriveType", driveTypeId);
esq.Filters.Add(typeFilter);
string sqlText = esq.GetSelectQuery(UserConnection).GetSqlText();
Set("SqlTextParameter", sqlText);
var entityCollection = esq.GetEntityCollection(UserConnection);
decimal sumTicketPrices = 0m;
int validCount = 0;
foreach (var entity in entityCollection) {
    int passengers = entity.GetTypedColumnValue<int>(passengerCountColumn.Name);
    decimal price = entity.GetTypedColumnValue<decimal>(priceColumn.Name);
    sumTicketPrices += price / passengers;
    validCount++;
}
decimal result = validCount > 0 ? sumTicketPrices / validCount : 0m;
Set("AvgTicketPriceParameter", result);
Set("AvgTicketPriceText", result.ToString("0.00") + " over " + validCount.ToString() + " yachts");
return true;
